// FimPortalClient — a typed, use-case-tailored client over the open (no-auth)
// endpoints of the FIM Portal API. Authenticated endpoints (uploads, converters,
// quality-check tools, token introspection) are intentionally not implemented.
//
// The surface is grouped by resource so usage reads naturally, e.g.
//   client.schemas.search({ name: "Geburt" })
//   client.processes.downloadVisualization(id, version, stufe, kodierung)
import { RequestEngine } from "./engine.js";
import { assertPagination, assertValid, detaillierungsstufeProblem, normalizeToken, pathSegment, tokenProblem, xzufiSourceProblem, } from "./validate.js";
import { CODE_LIST_PARAMS, DOCUMENT_PROFILE_SEARCH_PARAMS, FIELD_SEARCH_PARAMS, GROUP_SEARCH_PARAMS, PROCESS_CLASS_SEARCH_PARAMS, PROCESS_SEARCH_PARAMS, SCHEMA_SEARCH_PARAMS, SERVICE_PROFILE_SEARCH_PARAMS, SERVICE_TEXT_SEARCH_PARAMS, XZUFI_FTS_LIST_PARAMS, XZUFI_LIST_PARAMS, assertParams, searchCsvQuery, } from "./filters.js";
const ACCEPT_XML = "application/xml";
const ACCEPT_PDF = "application/pdf";
/** The XZuFi `source` path segment of a service text, checked against XzufiSourceValues. */
function sourceSegment(source) {
    return enumSegment("source", source, xzufiSourceProblem);
}
/** The `stufe` path segment of a process, checked against DetaillierungsstufeValues. */
function stufeSegment(stufe) {
    return enumSegment("stufe", stufe, detaillierungsstufeProblem);
}
/** An enumerated path segment: a token (trimmed, NFC, nothing invisible), then one of its values. */
function enumSegment(name, value, problem) {
    const token = typeof value === "string" ? normalizeToken(assertValid(name, value, tokenProblem)) : value;
    assertValid(name, token, problem);
    return pathSegment(name, token);
}
// Every path id goes through pathSegment(name, value): it rejects a blank id with
// FimValidationError (an empty segment would re-target the request to a collection
// or a versions list) and percent-encodes the rest. "." and ".." pass encoding
// unchanged; the engine rejects those (see RequestEngine.buildUrl).
/** Search/filter and retrieve XDatenfelder Datenschemata. */
class SchemasResource {
    e;
    constructor(e) {
        this.e = e;
    }
    async search(params = {}, options = {}) {
        const query = assertParams(params, SCHEMA_SEARCH_PARAMS, "schemas.search", options);
        assertPagination(params ?? {});
        return this.e.getJson("/api/v1/schemas", query, "page");
    }
    /** All versions of a schema, ascending. */
    async versions(fimId) {
        return this.e.getJson(`/api/v1/schemas/${pathSegment("fimId", fimId)}`, undefined, "list");
    }
    /** A full schema. Pass version `"latest"` for the newest. */
    async get(fimId, fimVersion = "latest") {
        return this.e.getJson(`/api/v1/schemas/${pathSegment("fimId", fimId)}/${pathSegment("fimVersion", fimVersion)}`, undefined, "record");
    }
    async downloadXdf(fimId, fimVersion = "latest") {
        return this.e.getRaw(`/api/v1/schemas/${pathSegment("fimId", fimId)}/${pathSegment("fimVersion", fimVersion)}/xdf`, ACCEPT_XML);
    }
    async qualityReport(fimId, fimVersion = "latest") {
        return this.e.getJson(`/api/v1/schemas/${pathSegment("fimId", fimId)}/${pathSegment("fimVersion", fimVersion)}/quality-report`, undefined, "record");
    }
}
